use vstd::prelude::*;
use vstd::vec::*;

type Matrix<T> = Vec<Vec<T>>;

verus! {

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (result: Matrix<i8>)
    requires
        shape.len() == 2,
        shape[0] > 0,
        shape[1] > 0,
        a.len() > 0,
        a.len() == shape[0] as usize || a.len() == shape[1] as usize,
    ensures
        result.len() == shape[0] as usize,
        forall |i: int| 0 <= i < result.len() ==> #[trigger] result[i].len() == shape[1] as usize,
        a.len() == shape[0] as usize ==> 
            forall |i: int, j: int| 
                0 <= i < result.len() && 0 <= j < result[i].len() ==> 
                    result[i][j] == a[i],
        a.len() == shape[1] as usize ==> 
            forall |i: int, j: int| 
                0 <= i < result.len() && 0 <= j < result[i].len() ==> 
                    result[i][j] == a[j],
{
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let a_len = a.len();
    
    // Validate assumptions (though not strictly required per problem statement)
    assert!(a_len > 0, "Array must have positive length");
    assert!(shape.len() == 2, "Shape must have exactly 2 elements");
    assert!(r > 0 && c > 0, "Both dimensions must be positive");
    assert!(a_len == r || a_len == c, 
            "Array length must match either R or C");
    
    proof {
        // Proof that the assertions match the preconditions
        assert(shape.len() == 2);
        assert(r > 0);
        assert(c > 0);
        assert(a_len > 0);
        assert(a_len == r || a_len == c);
    }
    
    let result = if a_len == r {
        // Treat as column vector: broadcast across columns
        (0..r)
            .map(|i| vec![a[i]; c])  // Create row with c copies of a[i]
            .collect()
    } else {
        // Treat as row vector: broadcast across rows
        let row = a.clone();  // The row vector to repeat
        (0..r)
            .map(|_| row.clone())  // Create r copies of the row
            .collect()
    };
    
    proof {
        // Verify the postconditions
        let result_len = result.len();
        assert(result_len == r);
        
        // Verify all rows have the correct length
        for i in 0..result_len {
            assert(result[i].len() == c);
        }
        
        // Verify the broadcast pattern based on which dimension matches
        if a_len == r {
            // Column vector case
            for i in 0..result_len {
                for j in 0..c {
                    assert(result[i][j] == a[i]);
                }
            }
        } else {
            // Row vector case
            for i in 0..result_len {
                for j in 0..c {
                    assert(result[i][j] == a[j]);
                }
            }
        }
    }
    
    result
}

} // verus!